{"cards": [{"node_code": "N_24324b88d1c0227a", "definition": "研究铁路地面信号显示装置（信号机）及其附属机构，包括色灯、臂板、LED等显示方式，以及信号机安装、结构、光源、透镜及故障安全设计。", "boundary": "本节点聚焦于“显示”与“指示”终端设备。边界在于区分“显示设备”与“控制逻辑”：信号机本身归本节点，控制信号机点亮的联锁逻辑归联锁节点；区分“地面信号”与“机车信号”：地面固定信号机归本节点，车载接收显示设备归区间闭塞与机车信号系统。若涉及信号机内部电路原理，归本节点；若涉及信号机供电电源，归供电节点。", "includes": ["色灯、臂板、LED等类型信号机的结构与工作原理", "信号机安装标准、建筑限界及故障安全设计", "信号机光源、透镜、机构及日常维护技术"], "excludes": ["控制信号机显示的联锁逻辑与进路控制", "车载机车信号接收与显示设备", "信号机专用供电电源系统"], "sibling_distinctions": [{"other_code": "N_239de9765a822e40", "rule": "区分依据为功能层级：信号机是执行显示的终端设备，联锁是控制信号机状态及道岔位置的安全逻辑系统；显示归本节点，控制归联锁。"}, {"other_code": "N_fad09c20e5bf9c08", "rule": "区分依据为位置与对象：地面固定信号机归本节点，安装在机车上的信号接收与显示装置归区间闭塞与机车信号系统。"}], "cross_boundary_rule": ""}, {"node_code": "N_40f2c353324ec40b", "definition": "研究利用钢轨作为导体传输信号电流，以检测轨道区段占用状态、传输行车信息的电路系统，涵盖制式、设备、调整及故障处理。", "boundary": "本节点聚焦于“轨道占用检测”与“信息传输”的电气基础。边界在于区分“检测/传输”与“控制”：轨道电路负责检测列车占用并传输低频/高频信息，归本节点；利用轨道电路信息进行的闭塞逻辑判断归区间闭塞节点。若涉及轨道电路的电气特性、绝缘节、送受电端设备，归本节点；若涉及轨道电路的供电电源，归供电节点。", "includes": ["各种制式（交流、直流、数字）轨道电路的原理与设备", "轨道电路区段划分、绝缘节设置及电气调整", "轨道电路故障诊断、测试方法及抗干扰技术"], "excludes": ["基于轨道电路信息的闭塞逻辑与进路控制", "轨道电路专用供电电源系统", "非轨道介质的列车定位技术（如GPS、应答器）"], "sibling_distinctions": [{"other_code": "N_fad09c20e5bf9c08", "rule": "区分依据为功能：轨道电路侧重“检测”与“传输”，即感知列车位置和传递信息；区间闭塞侧重“逻辑”与“控制”，即根据检测信息决定列车能否进入区段。"}, {"other_code": "N_24324b88d1c0227a", "rule": "区分依据为设备类型：轨道电路是检测与传输的电气系统，信号机是显示行车命令的光学/机械装置；两者常配合使用，但技术原理不同。"}], "cross_boundary_rule": ""}, {"node_code": "N_239de9765a822e40", "definition": "研究车站内信号机、道岔及进路之间的安全联锁关系，确保行车作业中设备状态互不冲突，涵盖联锁原理、系统架构、软件逻辑及故障安全。", "boundary": "本节点聚焦于“车站”范围内的“安全逻辑控制”。边界在于区分“车站联锁”与“区间闭塞”：车站联锁处理站内进路、道岔与信号机关系，归本节点；区间闭塞处理区间列车运行间隔，归区间闭塞节点。区分“联锁逻辑”与“信号显示”：联锁是控制大脑，信号机是执行终端；若内容涉及联锁表、进路建立逻辑、故障安全机制，归本节点。", "includes": ["车站联锁系统（继电、计算机）的原理、架构与软件设计", "进路、道岔、信号机之间的联锁关系与逻辑表编制", "联锁系统的故障安全机制、测试验证及维护管理"], "excludes": ["区间列车运行间隔控制（区间闭塞）", "信号机、道岔等具体硬件设备的机械结构", "调度集中系统（CTC）的远程指挥功能（侧重联锁逻辑时归本节点，侧重指挥时归调度）"], "sibling_distinctions": [{"other_code": "N_fad09c20e5bf9c08", "rule": "区分依据为空间范围与控制对象：车站联锁侧重站内进路、道岔与信号机的互锁关系；区间闭塞侧重区间内列车运行间隔与通过权控制。"}, {"other_code": "N_24324b88d1c0227a", "rule": "区分依据为控制与执行：联锁是控制逻辑系统，决定信号机能否开放；信号机是被控制的显示设备。"}], "cross_boundary_rule": "若内容涉及“计算机联锁”，侧重逻辑算法、软件架构及故障安全归本节点；若侧重硬件电路板设计，可关联信号器材与设备，但核心逻辑归本节点。"}]}
